INSERT INTO `contacts` VALUES (1,'Sana M.','sana@example.com','+92 300 1234567',NULL,'mobile','Mobile app for our clinic','$3,000 ? $5,000',NULL,NULL,'Hi Amaanullah, we?re a small clinic in Lahore and want an appointment app for patients with reminders. Could you share a rough timeline and how you usually work? Thanks, Sana',NULL,'119.160.118.42','new','2026-10-23 23:39:28'),(2,'James W.','james@example.com','+44 20 7946 0912',NULL,'crm','SaaS MVP ? 8 week timeline?','$5,000 ? $10,000',NULL,NULL,'We have a validated idea for a B2B scheduling SaaS. Looking for a Laravel developer to build an MVP. Is an 8-week timeline realistic?',NULL,'82.165.197.1','read','2026-10-23 21:39:28'),(3,'Fatima Z.','fatima@example.com','+92 321 9876543',NULL,'web_apps','Laravel code audit','$1,000 ? $3,000',NULL,NULL,'Our Laravel 9 app is slow and we?re worried about security. Do you offer one-off audits?',NULL,'39.40.12.85','read','2026-10-23 01:39:28'),(4,'Daniel P.','daniel@example.com','+44 7700 900077',NULL,'chat','Partnership','Retainer',NULL,NULL,'I run a small agency in London and need overflow help on PHP projects.',NULL,'51.148.132.8','read','2026-10-20 01:39:28'),(5,'Usman A.','usman@example.com','+92 333 5551234',NULL,'automation','Re: proposal','$3,000 ? $5,000',NULL,NULL,'Thanks for the proposal, we?ll review it this week.',NULL,'115.186.189.60','read','2026-09-30 01:39:28');
