  `domain` varchar(150) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `banner` varchar(255) DEFAULT NULL,
  `banner_alt` varchar(255) DEFAULT NULL,
  `client` varchar(255) DEFAULT NULL,
  `industry` varchar(255) DEFAULT NULL,
  `role` varchar(255) DEFAULT NULL,
  `timeline` varchar(100) DEFAULT NULL,
  `platform` varchar(150) DEFAULT NULL,
  `project_status` varchar(100) NOT NULL DEFAULT 'Completed',
  `tech_chips` varchar(255) DEFAULT NULL,
  `tldr` text DEFAULT NULL,
  `key_results` text DEFAULT NULL,
  `body_json` longtext DEFAULT NULL,
  `body_html` longtext DEFAULT NULL,
  `status` enum('draft','in_review','scheduled','published','trash') NOT NULL DEFAULT 'published',
  `published_at` datetime DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
