  `views_count` int(10) unsigned NOT NULL DEFAULT 0,
  `cta_title` varchar(255) DEFAULT NULL,
  `cta_text` text DEFAULT NULL,
  `cta_label` varchar(100) DEFAULT NULL,
  `related_project_ids` varchar(255) DEFAULT NULL,
  `focus_keyword` varchar(150) DEFAULT NULL,
  `seo_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `canonical_url` varchar(255) DEFAULT NULL,
  `og_image` varchar(255) DEFAULT NULL,
  `is_indexed` tinyint(1) NOT NULL DEFAULT 1,
  `faq_schema` tinyint(1) NOT NULL DEFAULT 1,
  `creative_work_schema` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `view` varchar(100) NOT NULL DEFAULT 'projects/show',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_proj_status` (`status`),
  KEY `idx_proj_cat` (`category_slug`),
  KEY `idx_proj_feat` (`is_featured`)
